import {materialSummary,materialHTML} from './live-material.js';
import {LiveGame,opposite} from './live-game.js';
import {drawBoard,choosePiece} from './mini-board.js';
import {saveGame,putRecord,getRecord} from './archive.js';
const $=id=>document.getElementById(id),key='plystreak-live-v1';let game,selected=null,flipped=false,busy=false,owned=false;
function error(e){$('storageStatus').textContent='Salvataggio non riuscito: esporta il PGN prima di uscire. '+(e?.message||'')}
function persist(){if(!game)return;const data=game.snapshot();try{localStorage.setItem(key,JSON.stringify(data))}catch(e){error(e)}putRecord({id:key,snapshot:data},'meta').catch(error);saveGame({id:data.id,pgn:data.pgn,source:'live',side:data.side,playedAt:data.created}).catch(error)}
function time(ms){const s=Math.ceil(ms/1000);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function clocks(){if(!game)return;for(const [id,c] of [['topClock',flipped?'w':'b'],['bottomClock',flipped?'b':'w']]){const el=$(id),left=game.remaining(c);el.firstElementChild.textContent=(c==='w'?'○ ':'● ')+(c==='w'?game.data.white:game.data.black);el.lastElementChild.textContent=game.data.minutes?time(left):'∞';el.classList.toggle('active',game.data.result==='*'&&!game.data.paused&&game.chess.turn()===c);el.classList.toggle('low',!!game.data.minutes&&left<30000)}}
function render(){if(!game)return;const material=materialSummary(game.chess);$('topMaterial').innerHTML=materialHTML(material,flipped?'w':'b');$('bottomMaterial').innerHTML=materialHTML(material,flipped?'b':'w');$('setup').hidden=true;$('game').hidden=false;document.body.classList.add('live-playing');const d=game.data,end=d.result!=='*',turn=game.chess.turn();$('status').textContent=end?`${d.result} · ${d.reason}`:d.paused?'Partita in pausa':`${turn==='w'?d.white:d.black} · tocca a te${game.chess.isCheck()?' · Scacco!':''}`;drawBoard($('liveBoard'),game.chess,{flipped,selected,disabled:end||d.paused||!owned,last:game.chess.history({verbose:true}).at(-1),draw:d.result==='1/2-1/2'});clocks();$('history').textContent=game.chess.history().map((m,i)=>(i%2===0?`${Math.floor(i/2)+1}. `:'')+m+(i%2?'\n':' ')).join('');$('history').scrollTop=$('history').scrollHeight;for(const id of ['pause','resign','offer','claim','claimOption'])$(id).hidden=end;for(const id of ['review','rematch','new'])$(id).hidden=!end;$('pause').textContent=d.paused?'Riprendi partita':'Pausa concordata';$('claim').disabled=!game.claimable()||d.paused;$('offer').disabled=!!d.offer||d.paused;$('resign').disabled=d.paused;$('accept').hidden=$('decline').hidden=end||!d.offer||d.offer===turn;$('notice').textContent=d.offer?`Patta offerta dal ${d.offer==='w'?'Bianco':'Nero'}. L’avversario può accettare, rifiutare o giocare.`:''}
function change(){persist();render()}
function live(){if(!game||!owned||game.data.result!=='*'||game.data.paused)return false;if(game.tick()){change();return false}return true}
function agree(message){return new Promise(resolve=>{const d=document.createElement('dialog'),p=document.createElement('p');p.textContent=message;d.append(p);for(const [label,value] of [['Conferma',true],['Annulla',false]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{d.close();d.remove();resolve(value)};d.append(b)}d.oncancel=e=>{e.preventDefault();d.remove();resolve(false)};document.body.append(d);d.showModal()})}
$('preset').onchange=()=>{$('custom').hidden=$('preset').value!=='custom'};
$('setup').onsubmit=e=>{e.preventDefault();if(!owned)return;let [minutes,increment]=$('preset').value==='custom'?[Number($('minutes').value),Number($('increment').value)]:$('preset').value.split(',').map(Number);if(!Number.isInteger(minutes)||minutes<0||minutes>180||!Number.isInteger(increment)||increment<0||increment>120)return;game=new LiveGame({minutes,increment,white:$('white').value.trim()||'Bianco',black:$('black').value.trim()||'Nero',side:$('side').value||null});selected=null;change();navigator.storage?.persist?.().catch(()=>{})};
$('liveBoard').onclick=async e=>{const sq=e.target.closest('[data-sq]')?.dataset.sq;if(!sq||busy||!live())return;const piece=game.chess.get(sq),turn=game.chess.turn();if(selected){const moves=game.chess.moves({square:selected,verbose:true}).filter(m=>m.to===sq);if(moves.length){busy=true;const origin=selected;const promotion=moves.some(m=>m.promotion)?await choosePiece(turn):undefined;busy=false;if(!live()||(moves.some(m=>m.promotion)&&!promotion))return;const move={from:origin,to:sq,...(promotion?{promotion}:{})};if($('intent').checked){$('intent').checked=false;if(game.claim(move)){selected=null;change();return}$('notice').textContent='Questa mossa non permette di reclamare patta. Scegli come proseguire.';return}if(game.move(move)){selected=null;if($('autoFlip').checked)flipped=game.chess.turn()==='b';change()}return}}selected=piece?.color===turn?sq:null;render()};
$('flip').onclick=()=>{flipped=!flipped;render()};$('autoFlip').onchange=()=>{if($('autoFlip').checked)flipped=game.chess.turn()==='b';render()};
$('pause').onclick=async()=>{if(!owned)return;if(await agree(game.data.paused?'Riprendere gli orologi?':'Entrambi i giocatori sono d’accordo sulla pausa? Il tempo continua fino alla conferma.')){game.pause();change()}};
$('resign').onclick=async()=>{if(!live())return;const c=game.chess.turn();if(await agree(`${c==='w'?'Il Bianco':'Il Nero'} vuole abbandonare?`)&&live()){game.resign();change()}};
$('offer').onclick=()=>{if(live()){game.data.offer=game.chess.turn();change()}};
$('accept').onclick=()=>{if(live()&&game.data.offer&&game.data.offer!==game.chess.turn()){game.finish('1/2-1/2','Patta concordata');change()}};
$('decline').onclick=()=>{if(live()){game.data.offer=null;change()}};
$('claim').onclick=()=>{if(live()&&game.claim())change()};
$('review').onclick=()=>{const d=game.snapshot();localStorage.setItem('plystreak-review-import',d.pgn);localStorage.setItem('plystreak-review-id',d.id);localStorage.setItem('plystreak-review-side',d.side||'');location.href='index.html?training=1&review=auto'};
$('export').onclick=async()=>{if(window.Capacitor?.isNativePlatform()){const file=new File([game.snapshot().pgn],'plystreak-dal-vivo.pgn',{type:'text/plain'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]})}catch{}return}const d=document.createElement('dialog'),a=document.createElement('textarea'),b=document.createElement('button');a.value=game.snapshot().pgn;a.readOnly=true;a.style.cssText='width:100%;height:45vh';b.textContent='Chiudi';b.onclick=()=>d.remove();d.append('Seleziona e copia il PGN.',a,b);document.body.append(d);d.showModal();return}const blob=new Blob([game.snapshot().pgn],{type:'application/x-chess-pgn'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='plystreak-dal-vivo.pgn';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('rematch').onclick=()=>{const d=game.data;game=new LiveGame({minutes:d.minutes,increment:d.increment,white:d.black,black:d.white,side:d.side?opposite(d.side):null});selected=null;change()};
$('new').onclick=()=>{$('game').hidden=true;$('setup').hidden=false;document.body.classList.remove('live-playing');game=null;localStorage.removeItem(key);putRecord({id:key,snapshot:null},'meta').catch(error)};
async function init(){owned=true;let raw;try{raw=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!raw)try{raw=(await getRecord(key,'meta'))?.snapshot}catch(e){error(e)}if(raw)try{game=LiveGame.restore(raw);game.tick();change()}catch{$('storageStatus').textContent='La partita salvata non è leggibile. Le partite archiviate restano nei Progressi.'}setInterval(()=>{if(game&&owned){if(game.tick())change();clocks()}},100);document.addEventListener('visibilitychange',()=>{if(game&&owned){game.tick();change()}})}
if(navigator.locks)navigator.locks.request('plystreak-live',{ifAvailable:true},async lock=>{if(!lock){$('setup').hidden=true;$('storageStatus').textContent='Gioco dal vivo è già aperto in un’altra scheda. Chiudila e ricarica questa pagina.';return}await init();await new Promise(()=>{})});else{init();window.addEventListener('storage',e=>{if(e.key===key){owned=false;$('storageStatus').textContent='Partita modificata in un’altra scheda. Chiudi questa pagina e continua nell’altra.';render()}})}
